export const omniTools: OmniTool[] = [
  ...coreTools,
  ...flagshipTools,
  ...physicalTools,
]

export const getOmniToolById  = (id: string) => omniTools.find(t => t.id === id)
export const getFlagshipTools = ()           => omniTools.filter(t => t.isFlagship)
export const getNewOmniTools  = ()           => omniTools.filter(t => t.isNew)
export const getPopularOmni   = ()           => omniTools.filter(t => t.isPopular)
export const getPhysicalTools = ()           => omniTools.filter(t => t.requiresImage)
export const getNonImageTools = ()           => omniTools.filter(t => !t.requiresImage)
export const getCoreTools     = ()           => coreTools
